#[path="program-host.rs"]mod program_host;
use js_runtime::{Runtime,Value,EnvId,JsResult};
fn print(rt:&mut Runtime,_:Value,args:&[Value],_:EnvId)->JsResult<Value>{let mut p=Vec::new();for &v in args{let s=rt.to_string(v)?;p.push(String::from_utf16_lossy(rt.string_units(s)));}println!("{}",p.join(" "));Ok(Value::Undefined)}
fn probe(rt:&mut Runtime,phase:i32)->JsResult<()>{let env=rt.global_env;let ctor=rt.lookup(env,"Uint8Array")?;let bytes=rt.uint8_array_from_bytes(ctor,vec![65])?;let fast=rt.try_native_decode_utf8(bytes,env)?.is_some();eprintln!("probe_phase:{phase}:direct_guard:{fast}");if phase>=0{let f=rt.lookup(env,"__nativeDecodeUTF8")?;let n=rt.objects.len();let out=rt.call_value(f,Value::Undefined,&[bytes])?;eprintln!("probe_phase:{phase}:actual_objects_delta:{}:out:{out:?}",rt.objects.len()-n);}Ok(())}
fn one_battle_probe(rt:&mut Runtime,this:Value,args:&[Value],env:EnvId)->JsResult<Value>{let original=rt.lookup(env,"originalRun")?;let mut args=args.to_vec();args[2]=Value::Number(1.0);args[3]=Value::Number(0.0);eprintln!("one_battle_start:objects:{}",rt.objects.len());let start=std::time::Instant::now();let report=rt.call_value(original,this,&args)?;eprintln!("one_battle_complete:elapsed_ms:{}:objects:{}",start.elapsed().as_secs_f64()*1000.0,rt.objects.len());let global=rt.global_env;let json=rt.lookup(global,"JSON")?;let key=rt.string("stringify");let stringify=rt.get(json,key)?;let text=rt.call_value(stringify,json,&[report])?;let Value::String(id)=text else{panic!("report serialization")};println!("ONE_BATTLE_REPORT:{}",String::from_utf16_lossy(rt.string_units(id)));Err(js_runtime::JsError::Unsupported("diagnostic stop after one real battle; remaining host tape intentionally unconsumed".into()))}
fn run()->JsResult<()>{let mut rt=Runtime::new();let env=rt.global_env;let global=Value::Object(rt.global_object);program_host::install(&mut rt)?;let printer=rt.make_closure_with_flags(print,env,0,"print",true,None);rt.declare(env,"print",printer)?;probe(&mut rt,-1)?;battle_unit_0::run(&mut rt,env,global)?; probe(&mut rt,0)?;
battle_unit_1::run(&mut rt,env,global)?; probe(&mut rt,1)?;
battle_unit_2::run(&mut rt,env,global)?; probe(&mut rt,2)?;
battle_unit_3::run(&mut rt,env,global)?; probe(&mut rt,3)?;
battle_unit_4::run(&mut rt,env,global)?; probe(&mut rt,4)?;
battle_unit_5::run(&mut rt,env,global)?; probe(&mut rt,5)?;let old=rt.lookup(env,"__nativeRun")?;let capture=rt.child_env(env);rt.declare(capture,"originalRun",old)?;let wrapper=rt.make_closure_with_flags(one_battle_probe,capture,6,"one_battle_probe",true,None);rt.assign(env,"__nativeRun",wrapper,true)?;battle_unit_6::run(&mut rt,env,global)?;Ok(())}
fn main(){if let Err(e)=run(){eprintln!("probe_error:{e:?}");std::process::exit(1);}}
